import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:mobile/core/location/photo_metadata.dart';

// Real JPEGs carrying real EXIF, generated by tool/make_exif_fixtures.py.
// Reading actual bytes is the point: a hand-rolled map of tags would not catch
// the rational-to-degrees and hemisphere handling, which is where this goes
// wrong in practice.
File _fixture(String name) => File('test/fixtures/$name');

void main() {
  group('GPS decoding', () {
    test('northern and eastern hemispheres stay positive', () async {
      final meta = await readPhotoMetadata(_fixture('gps_north_east.jpg'));
      // Arc de Triomphe.
      expect(meta.position, isNotNull);
      expect(meta.position!.latitude, closeTo(48.8584, 0.0005));
      expect(meta.position!.longitude, closeTo(2.2945, 0.0005));
    });

    test('a southern latitude is negative', () async {
      final meta = await readPhotoMetadata(_fixture('gps_south_east.jpg'));
      // Sydney Opera House — the sign is the whole test.
      expect(meta.position!.latitude, closeTo(-33.8568, 0.0005));
      expect(meta.position!.longitude, closeTo(151.2153, 0.0005));
    });

    test('a western longitude is negative', () async {
      final meta = await readPhotoMetadata(_fixture('gps_south_west.jpg'));
      // Machu Picchu — both signs negative.
      expect(meta.position!.latitude, closeTo(-13.1631, 0.0005));
      expect(meta.position!.longitude, closeTo(-72.5450, 0.0005));
    });

    test('a photo without GPS reports no position', () async {
      final meta = await readPhotoMetadata(_fixture('no_gps.jpg'));
      expect(meta.position, isNull);
    });

    test('a photo with no EXIF at all reports nothing', () async {
      final meta = await readPhotoMetadata(_fixture('no_exif_at_all.jpg'));
      expect(meta.position, isNull);
      expect(meta.takenAt, isNull);
    });
  });

  group('capture time', () {
    test('is read from DateTimeOriginal', () async {
      final meta = await readPhotoMetadata(_fixture('gps_north_east.jpg'));
      expect(meta.takenAt, DateTime(2026, 3, 14, 9, 30, 0));
    });

    test('is read even when the photo carries no GPS', () async {
      final meta = await readPhotoMetadata(_fixture('no_gps.jpg'));
      expect(meta.takenAt, DateTime(2026, 1, 2, 18, 45, 10));
    });
  });

  group('failure handling', () {
    test('a missing file yields empty metadata rather than throwing', () async {
      final meta = await readPhotoMetadata(File('test/fixtures/nope.jpg'));
      expect(meta.position, isNull);
      expect(meta.takenAt, isNull);
    });

    test('a non-image yields empty metadata', () async {
      final junk = File('${Directory.systemTemp.path}/not_an_image.jpg')
        ..writeAsBytesSync(List<int>.filled(64, 7));
      addTearDown(() => junk.deleteSync());

      final meta = await readPhotoMetadata(junk);
      expect(meta.position, isNull);
    });
  });
}
